using System.Text.Json;using Microsoft.Data.Sqlite;using WAID.Application.Abstractions;namespace WAID.Infrastructure.Persistence;
public sealed class SqliteWindowsUpdateHealthRepository(WaidDatabase database):IWindowsUpdateHealthRepository{private static readonly JsonSerializerOptions Options=new(JsonSerializerDefaults.Web);public async Task<WindowsUpdateHealthReport?> GetLatestAsync(CancellationToken t){await using var c=database.OpenConnection();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT report_json FROM windows_update_analysis_runs ORDER BY generated_utc DESC LIMIT 1;";var j=await cmd.ExecuteScalarAsync(t).ConfigureAwait(false) as string;return j is null?null:JsonSerializer.Deserialize<WindowsUpdateHealthReport>(j,Options);}public async Task SaveAsync(UpdateEvidenceSnapshot snapshot,WindowsUpdateHealthReport report,CancellationToken t){await using var c=database.OpenConnection();await using var tx=(SqliteTransaction)await c.BeginTransactionAsync(t).ConfigureAwait(false);await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText="INSERT INTO windows_update_analysis_runs(id,generated_utc,snapshot_json,report_json,outcomes_json) VALUES($id,$time,$snapshot,$report,'[]');";cmd.Parameters.AddWithValue("$id",report.Id.ToString());cmd.Parameters.AddWithValue("$time",report.GeneratedAtUtc.ToString("O"));cmd.Parameters.AddWithValue("$snapshot",JsonSerializer.Serialize(snapshot,Options));cmd.Parameters.AddWithValue("$report",JsonSerializer.Serialize(report,Options));await cmd.ExecuteNonQueryAsync(t).ConfigureAwait(false);await tx.CommitAsync(t).ConfigureAwait(false);}}
